<template>
  <q-dialog v-model="shown" persistent :maximized="false" transition-show="slide-up" transition-hide="slide-down" @hide="emit('closed')">
    <q-card class="task-card text-white">
      <q-card-section class="task-header"><div><div class="eyebrow">TASK CENTER</div><div class="text-h6">{{ task?.name || title || '正在执行' }}</div><div class="text-caption text-grey-5">{{ task?.status || status || '正在准备…' }}</div></div><q-btn v-if="task?.canAbort || busy" flat round icon="close" color="orange" @click="emit('cancel')" /></q-card-section>
      <q-linear-progress :value="progress" color="primary" track-color="grey-8" rounded class="q-mx-lg" />
      <q-card-section class="task-body"><div class="task-progress-row"><strong>{{ progressLabel }}</strong><span v-if="task?.transferRate">{{ formatRate(task.transferRate) }}<span v-if="eta"> · {{ eta }}</span></span></div><div v-if="task?.details" class="task-details">{{ task.details }}</div><q-banner v-if="task?.failReason" dense class="task-error q-mb-sm">{{ task.failReason }}</q-banner><div v-if="stepRows.length || childRows.length" class="task-section-label">下载与处理明细</div><q-list v-if="stepRows.length" dense class="task-steps"><q-item v-for="step in stepRows" :key="step.id"><q-item-section avatar><q-icon :name="step.finished ? 'check_circle' : step.state === 'failed' ? 'error' : step.state === 'running' ? 'sync' : 'radio_button_unchecked'" :color="step.finished ? 'positive' : step.state === 'failed' ? 'negative' : step.state === 'running' ? 'primary' : 'grey'" /></q-item-section><q-item-section><q-item-label>{{ step.status || step.id }}</q-item-label><q-item-label v-if="step.details" caption class="task-detail-line">{{ step.details }}</q-item-label><q-linear-progress v-if="step.total > 0" :value="ratio(step.current, step.total)" color="primary" track-color="grey-8" rounded class="task-step-progress" /></q-item-section><q-item-section side>{{ step.current != null && step.total > 0 ? `${formatBytes(step.current)} / ${formatBytes(step.total)}` : '' }}</q-item-section></q-item></q-list><q-list v-if="childRows.length" dense class="task-children"><q-item v-for="row in childRows" :key="row.id"><q-item-section avatar><q-icon :name="row.item.finished || row.item.successful ? 'check_circle' : row.item.state === 'failed' ? 'error' : row.item.running ? 'sync' : 'radio_button_unchecked'" :color="row.item.finished || row.item.successful ? 'positive' : row.item.state === 'failed' ? 'negative' : row.item.running ? 'primary' : 'grey'" /></q-item-section><q-item-section :style="{ paddingLeft: `${row.level * 12}px` }"><q-item-label>{{ taskLabel(row.item) }}</q-item-label><q-item-label v-if="row.item.details || row.item.status" caption class="task-detail-line">{{ row.item.details || row.item.status }}</q-item-label><q-linear-progress v-if="childTotal(row.item) > 0" :value="ratio(childCurrent(row.item), childTotal(row.item))" color="primary" track-color="grey-8" rounded class="task-step-progress" /></q-item-section><q-item-section side>{{ childTotal(row.item) > 0 ? `${formatBytes(childCurrent(row.item))} / ${formatBytes(childTotal(row.item))}` : '' }}</q-item-section></q-item></q-list></q-card-section>
      <q-card-actions align="right"><q-btn flat label="后台运行" :disable="!canBackground" @click="shown=false" /><q-btn v-if="task?.finished" color="primary" label="完成" @click="shown=false" /><q-btn v-else flat color="orange" label="取消任务" @click="emit('cancel')" /></q-card-actions>
    </q-card>
  </q-dialog>
</template>
<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
const props = defineProps<{ busy: boolean; execute: (op: string, p?: Record<string, unknown>) => Promise<any>; title?: string; status?: string; snapshot?: any; open?: boolean }>();
const emit = defineEmits<{ cancel: []; closed: []; updated: [task: any] }>();
const shown = ref(false); const polled = ref<any>(null); let timer: ReturnType<typeof setInterval> | undefined; let pollInFlight = false;
const task = computed(() => props.snapshot || polled.value); const steps = computed(() => Array.isArray(task.value?.steps) ? task.value.steps : []); const done = computed(() => isFinished(task.value)); const progress = computed(() => { const t = Number(task.value?.totalProgress || task.value?.total || 0); const p = Number(task.value?.progress || task.value?.current || 0); return t > 0 ? Math.max(0, Math.min(1, p / t)) : done.value ? 1 : 0; }); const progressLabel = computed(() => progress.value ? `${Math.round(progress.value * 100)}%` : (done.value ? '已完成' : '进行中')); const canBackground = computed(() => !props.busy || done.value); const stepRows = computed(() => steps.value.filter((step:any) => step && (step.status || step.details || Number(step.total) > 0))); const childRows = computed(() => flattenChildren(task.value?.children)); const eta = computed(() => { const rate = Number(task.value?.transferRate || 0); const total = Number(task.value?.totalProgress || 0); const current = Number(task.value?.progress || 0); return rate > 0 && total > current ? formatDuration((total - current) / rate) : ''; });
function isFinished(value:any) { return Boolean(value?.finished) || value?.running === false || ['succeeded', 'failed', 'aborted', 'finished', 'completed', 'cancelled', 'canceled'].includes(String(value?.state || value?.status || '').toLowerCase()); }
function flattenChildren(children:any, level = 0, rows:any[] = []) { if (!Array.isArray(children)) return rows; for (const item of children) { if (!item) continue; rows.push({ item, level, id: `${level}:${item.id || item.type || rows.length}` }); flattenChildren(item.children, level + 1, rows); } return rows; }
function taskLabel(item:any) { const fileName = item.source?.fileName; if (fileName) return fileName; return item.name || item.status || item.details || item.type || '子任务'; }
function childCurrent(item:any) { return Number(item.progress ?? item.current ?? 0); }
function childTotal(item:any) { return Number(item.totalProgress ?? item.total ?? 0); }
function ratio(current:any, total:any) { const c = Number(current), t = Number(total); return t > 0 ? Math.max(0, Math.min(1, c / t)) : 0; }
function formatBytes(value:any) { const n = Number(value); if (!Number.isFinite(n) || n < 0) return ''; if (n < 1024) return `${Math.round(n)} B`; const units = ['KB','MB','GB','TB']; let size = n / 1024, index = 0; while (size >= 1024 && index < units.length - 1) { size /= 1024; index++; } return `${size.toFixed(size >= 100 ? 0 : 1)} ${units[index]}`; }
function formatDuration(value:any) { const seconds = Math.max(0, Math.round(Number(value))); if (seconds < 60) return `${seconds}s`; const minutes = Math.floor(seconds / 60); return minutes < 60 ? `${minutes}m ${seconds % 60}s` : `${Math.floor(minutes / 60)}h ${minutes % 60}m`; }
function formatRate(value: any) { const n = Number(value); return Number.isFinite(n) && n > 0 ? `${formatBytes(n)}/s` : ''; }
async function poll() { if ((!props.busy && !props.open && !props.snapshot) || pollInFlight) return; pollInFlight = true; try { const value = await props.execute('task.status'); if (value && !isFinished(value)) { polled.value = value; emit('updated', value); shown.value = true; } else { polled.value = null; shown.value = false; if (value) emit('updated', value); } } catch { /* Ordinary API calls can run without a tracked task. */ if (!props.snapshot) { polled.value = null; shown.value = false; } } finally { pollInFlight = false; } }
watch(() => props.busy, (busy) => { if (busy) { void poll(); } else if (!props.snapshot) { polled.value = null; shown.value = false; } });
watch(() => props.snapshot, (value) => { if (value && !isFinished(value)) { polled.value = value; shown.value = true; } else if (!value) { polled.value = null; shown.value = false; } else { polled.value = null; shown.value = false; } });
watch(() => props.open, (value) => { if (value) { shown.value = true; void poll(); } });
onMounted(() => { timer = setInterval(() => void poll(), 450); }); onUnmounted(() => { if (timer) clearInterval(timer); });
</script>
<style scoped>
.task-card{width:620px;max-width:94vw;min-width:0;overflow:hidden;background:rgba(29,29,38,.96)!important;border:1px solid rgba(255,255,255,.12);border-radius:20px}.task-header{display:flex;align-items:flex-start;justify-content:space-between;min-width:0}.task-body{min-width:0;max-width:100%;overflow:hidden}.eyebrow{font-size:10px;letter-spacing:.16em;color:#a5b4fc;font-weight:700}.task-progress-row{display:flex;justify-content:space-between;gap:12px;min-width:0;margin:12px 0;color:rgba(255,255,255,.75)}.task-progress-row>*{min-width:0}.task-details{max-width:100%;margin-bottom:10px;color:rgba(255,255,255,.55);font-size:12px;overflow-wrap:anywhere;word-break:break-word}.task-error{color:#fecaca;background:rgba(185,28,28,.22);overflow-wrap:anywhere}.task-section-label{margin:14px 0 6px;color:rgba(255,255,255,.5);font-size:11px;font-weight:700;letter-spacing:.08em}.task-steps,.task-children{max-height:280px;min-width:0;overflow:auto;background:rgba(255,255,255,.035);border-radius:10px}.task-children{margin-top:8px;background:rgba(129,140,248,.06)}.task-steps :deep(.q-item),.task-children :deep(.q-item){min-height:48px}.task-steps :deep(.q-item__section),.task-children :deep(.q-item__section){min-width:0}.task-steps :deep(.q-item__label),.task-children :deep(.q-item__label){overflow-wrap:anywhere;word-break:break-word}.task-detail-line{overflow-wrap:anywhere;word-break:break-word;white-space:normal}.task-step-progress{margin-top:5px}.task-card :deep(.q-btn){text-transform:none}
</style>
